policies.inbound:



	@(context.Request.Headers.GetValueOrDefault("x-S7P-id", Guid.NewGuid().ToString()))










<set-variable name="throttleState" value="@{
	JObject loaded = context.Variables.GetValueOrDefault("throttleState", null);
	JObject map = (loaded != null && loaded["backends"] != null && loaded["backends"].Type == JTokenType.Object) ? (JObject)loaded["backends"] : new JObject();
	return new JObject { ["dirty"] = false, ["backends"] = map };
}" />
<set-variable name="listBackends" value="@{
	JArray backends = (JArray)context.Variables["listBackends"];
	JObject state = (JObject)((JObject)context.Variables["throttleState"])["backends"];
	DateTime now = DateTime.UtcNow;
	foreach (JObject b in backends) {
		DateTime wakeAt = state.Value(b.Value("affinity")) ?? DateTime.MinValue;
		bool isThrottling = wakeAt > now;
		b["isThrottling"] = isThrottling;
		b["retryAfter"] = isThrottling ? wakeAt : DateTime.MinValue;
	}
	return backends;
}" />


<set-variable name="RequestAffinityBackendIdx" value="@{
	string affinityHeaderName = (string)context.Variables["AffinityHeaderName"];
	string affinityHeader = context.Request.Headers.GetValueOrDefault(affinityHeaderName, "");

	// Find the backend with the matching affinity
	if (!string.IsNullOrEmpty(affinityHeader)) {
		JArray backends = (JArray)context.Variables["listBackends"];
		for (int i = 0; i < backends.Count; i++) {
			JObject backend = (JObject)backends[i];
			if (string.Equals(backend["affinity"]?.ToString(), affinityHeader, StringComparison.OrdinalIgnoreCase)) {
				return i;  // Return the index of the matching backend
			}
		}
	}

	// Return -1 if no affinity header or no match found
	return -1;
}" />

<set-variable name="PriBackendIndxs" value="@{
	JArray list =  new JArray();
	JArray backends = (JArray)context.Variables["listBackends"];
	int requestPriority = (int)context.Variables["RequestPriority"];
	for (int i = 0; i < backends.Count; i++) {
		JObject backend = (JObject)backends[i];
		if (backend["acceptablePriorities"]?.Values().Contains(requestPriority) == true) {
			list.Add(i);
		}
	}
	return list;
}" />
<set-variable name="RetryCount" value="@{
	return ((JObject)context.Variables["priorityCfg"])
		.GetValue(context.Variables.GetValueOrDefault("RequestPriority", 3).ToString())?
		.Value("retryCount") ?? 1;
}" />
<set-variable name="RequeueAllowed" value="@{
	return ((JObject)context.Variables["priorityCfg"])
		.GetValue(context.Variables.GetValueOrDefault("RequestPriority", 3).ToString())?
		.Value("requeue") ?? true;
}" />





<set-variable name="lastPolicyError" value="@{
	// Initialize or reuse
	JArray arr = context.Variables.GetValueOrDefault("lastPolicyError", new JArray());
	arr.Clear();
	arr.Add(new JObject {
		{ "code", "init" },
		{ "message", "noError" }
	});
	return arr;
}" />


<set-variable name="activityLog" value="@{
	// Request Start
	JArray arr = context.Variables.GetValueOrDefault("activityLog", new JArray());
	arr.Clear();
	arr.Add(new JObject {
		{ "Elapsed", context.Elapsed.TotalSeconds.ToString("F3")},
		{ "message", "Begin" }
	});
	return arr;
}" />


<set-variable name="DbgStr" value="@{
	var headers = context.Request.Headers;
	if (!string.Equals(headers.GetValueOrDefault("S7PDEBUG", ""), "true", StringComparison.OrdinalIgnoreCase)) {
		return "";
	}

	string priorityHeaderName = (string)context.Variables["priorityHeaderName"];
	JObject dbgObj = new JObject {
		{ "Proxy-Queue-Duration", headers.GetValueOrDefault("x-Request-Queue-Duration", "N/A") },
		{ "Proxy-Process-Duration", headers.GetValueOrDefault("x-Request-Process-Duration", "N/A") },
		{ "S7PID", headers.GetValueOrDefault("x-S7P-ID", "N/A") },
		{ priorityHeaderName, headers.GetValueOrDefault(priorityHeaderName, "N/A") },
		{ "Priority", context.Variables.GetValueOrDefault("RequestPriority", 3) }
	};

	return string.Join(" | ", dbgObj.Properties().Select(p => p.Name + ": " + p.Value));
}" />

set-header.value:
@{
				string dbgStr = context.Variables.GetValueOrDefault("DbgStr", "");
				JArray actLog = context.Variables.GetValueOrDefault("activityLog", new JArray());
				string result = string.Join(" | ", actLog.Select(entry =>
					((JObject)entry).Value("Elapsed") + "s " + ((JObject)entry).Value("message")
				));
				result = string.IsNullOrEmpty(dbgStr) ? result : dbgStr + " | " + result;
				return result.Length > 4000 ? result.Substring(0, 4000) + "..." : result;
			}

@{
				JArray errArr = context.Variables.GetValueOrDefault("lastPolicyError", new JArray());
				return errArr.Count == 0 ? "" : errArr.ToString(Newtonsoft.Json.Formatting.None);
			}
